                                "kaloud-sansaris-vitria": "301",
                                "blade-hookah": "285",
                                "mangueira-wookah": "311",
                                "xkah-eletronic": "277",
                                "la-capsula-bowl": "295",
                                "seven-bowl": "297",
                                "piteira-wookah": "313",
