                                "carvoes-e-aluminios": "255",
                            "carvoes": "261",
                                                "predator-": "289",
                                "cosmo-bowl-": "293",
                                "borrachas-de-vedacao": "129",
                                "essencias-": "247",
                                "marca-old-bowl": "235",
                        };

    const initCustomMegaMenu = () => {
        const triggers = document.querySelectorAll('.js-custom-mega-trigger');
        if (triggers.length === 0) return;

        triggers.forEach(menuItem => {
            menuItem.addEventListener('mouseenter', function() {
                const lists = this.querySelectorAll('.product-list-custom-inject');

                lists.forEach(list => {
                    if (list.getAttribute('data-loaded') === 'true') return;

                    const url = list.getAttribute('data-url');
                    if (!url) return;

                    const slug = url.split('/').filter(Boolean).pop().toLowerCase();
                    const catId = trayCategoryMap[slug];

                    if (!catId) {
                        list.innerHTML = '<li><a href="'+url+'">View all models</a></li>';
                        return;
                    }

                    fetch(`/web_api/products?category_id=${catId}&limit=6`)
                        .then(res => res.json())
                        .then(data => {
                            if (data.Products && data.Products.length > 0) {
                                let html = '';
                                data.Products.forEach(p => {
                                    const prod = p.Product;
                                    html += `<li><a href="${prod.url.https}" title="${prod.name}">${prod.name}</a></li>`;
                                });
                                list.innerHTML = html;
                                list.setAttribute('data-loaded', 'true');
                            } else {
                                list.innerHTML = '<li><span style="color:#bbb; font-size:12px;">No products at the moment</span></li>';
                            }
                        })
                        .catch(() => {
                            list.innerHTML = '<li><span style="color:#bbb; font-size:12px;">Unavailable</span></li>';
                        });
                });
            });
        });
    };

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        initCustomMegaMenu();
    } else {
        window.addEventListener('load', initCustomMegaMenu);
    }
})();

